  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  // C-001 is gold (5%), but explicit 0% should win
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice mixes tier and explicit discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 },
      { sku: 'BRAND-BOOK', qty: 2, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  // C-001 is gold (5%)
  assert.equal(r.value.lines[0].discountPercent, 5);
  // Explicit 15%
  assert.equal(r.value.lines[1].discountPercent, 15);
  // Explicit 0%
  assert.equal(r.value.lines[2].discountPercent, 0);
});

test('createInvoice tier discount affects invoice totals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);

  const totals = invoiceTotals(r.value);
  // 5 * 9500 = 47500, 5% discount = 2375
  // total = 47500 - 2375 = 45125
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.total, 45125);
});

